#!/usr/bin/env python3
"""Compile the actual pure bucket-prior code; no UI, camera or actuator linked.
Optional args are an immutable saved WorkspaceDetector directory and a diagnostic
matrix JSON. Neither fixture nor algorithm starts a source or grants authority.
"""
import pathlib, subprocess, sys, tempfile
repo=pathlib.Path(__file__).resolve().parents[1]
source=(repo/"Cerebro/ROBWorkspaceSearchPlan.swift").read_text()
start=source.index("enum ROBWorkspaceBucketOpeningPrior {")
end=source.index("/// Visual rehearsal only.",start)
helper="import Foundation\nimport simd\n"+source[start:end]
main='import Foundation\nimport AppKit\nimport simd\n@main enum Fixture {\n static func main()throws {\n let tilt=acos(58.0/70),c=cos(tilt),s=sin(tilt)\n let T=simd_double4x4(SIMD4(1,0,0,0),SIMD4(0,-c,-s,0),SIMD4(0,s,-c,0),SIMD4(0,0,1,1))\n func depth(_ x:Int,_ y:Int)->UInt16? {let z=1/(c+Double(y-240)/500*s);return UInt16((z*1000).rounded())}\n func color(_ x:Int,_ y:Int)->SIMD3<Double>? {let q=Double(x-320)/70;guard abs(q)<1 else{return SIMD3(0.2,0.2,0.2)};let upper=235-58*sqrt(1-q*q),lower=293+42*sqrt(1-q*q);guard Double(y)>=upper,Double(y)<=lower else{return SIMD3(0.2,0.2,0.2)};if Double(y)<upper+5{return SIMD3(1,0.55,0.02)};return SIMD3(0.82,0.15,0.04)}\n func run(_ depthProvider:(Int,Int)->UInt16?,_ colorProvider:(Int,Int)->SIMD3<Double>?)->ROBWorkspaceBucketOpeningPrior.Estimate? {ROBWorkspaceBucketOpeningPrior.estimate(box:[0.38,0.35,0.62,0.75],width:640,height:480,fx:500,fy:500,cx:320,cy:240,cameraToRobot:T,depth:depthProvider,color:colorProvider)}\n\n  guard let q=run(depth,color) else{fatalError("Independent rendered RGB opening/floor prior rejected")}\n  precondition(q.evidence.valid && q.radius>=0.068 && q.evidence.assumedHeightToOpeningDiameterRange==[0.8,1.2])\n  precondition(q.evidence.assumedBottomToOpeningRadiusRange==[0.6,1.0])\n  let encoded=try JSONEncoder().encode(q.evidence),decoded=try JSONDecoder().decode(ROBWorkspaceBucketOpeningPrior.Evidence.self,from:encoded)\n  precondition(decoded.valid && decoded.commonOpeningRadiusMeters==q.radius)\n  precondition(run({_,_ in nil},color)==nil,"No floor depth must block the prior")\n  precondition(run(depth,{_,_ in nil})==nil,"No RGB cannot establish an opening")\n  precondition(run(depth,{_,_ in SIMD3(0.8,0.2,0.1)})==nil,"Uniform orange must not create an opening")\n  func flatLid(_ x:Int,_ y:Int)->SIMD3<Double>? {let u=Double(x-320)/70,v=Double(y-235)/58;return u*u+v*v<1 ? SIMD3(0.8,0.2,0.1):SIMD3(0.2,0.2,0.2)}\n  precondition(run(depth,flatLid)==nil,"A flat solid orange ellipse is not a bucket opening")\n  precondition(run({_,_ in 100},color)==nil,"Out-of-range floor values are not support")\n  print("PASS actual source bucket prior: independent contour/floor positive, typed assumptions/roundtrip, missing evidence and solid-lid negatives")\n  if CommandLine.arguments.count==3 {try saved(URL(fileURLWithPath:CommandLine.arguments[1]),URL(fileURLWithPath:CommandLine.arguments[2]))}\n }\n static func saved(_ root:URL,_ matrixURL:URL)throws {\n  let meta=try JSONSerialization.jsonObject(with:Data(contentsOf:root.appendingPathComponent("last-bucket-depth.json"))) as! [String:Any]\n  let depth=try Data(contentsOf:root.appendingPathComponent("last-bucket-depth.u16")),image=NSBitmapImageRep(data:try Data(contentsOf:root.appendingPathComponent("last-bucket-input.jpg")))!\n  let matrices=try JSONSerialization.jsonObject(with:Data(contentsOf:matrixURL)) as! [String:[Double]],m=matrices["8000"]!\n  let T=simd_double4x4((0..<4).map {i in SIMD4(m[i*4],m[i*4+1],m[i*4+2],m[i*4+3])})\n  let box=(meta["boxes"] as! [[Double]])[0]\n  func mm(_ x:Int,_ y:Int)->UInt16? {let o=(y*640+x)*2;return UInt16(depth[o])|UInt16(depth[o+1])<<8}\n  func rgb(_ x:Int,_ y:Int)->SIMD3<Double>? {guard let c=image.colorAt(x:x,y:y)?.usingColorSpace(.deviceRGB) else{return nil};return SIMD3(c.redComponent,c.greenComponent,c.blueComponent)}\n  guard let actual=ROBWorkspaceBucketOpeningPrior.estimate(box:box,width:640,height:480,fx:meta["fx"]as!Double,fy:meta["fy"]as!Double,cx:meta["cx"]as!Double,cy:meta["cy"]as!Double,cameraToRobot:T,depth:mm,color:rgb) else{fatalError("Supplied saved data failed opening prior")}\n  precondition(actual.evidence.valid && actual.radius>=0.068)\n  print("PASS supplied immutable saved bucket: common radius \\(actual.radius)m, center \\(actual.center), explicit shape assumptions; no measured rim/registration claim")\n }\n}\n'
# The prior reserves the common opening disk instead of using the legacy offset.
assert 'bucket.bucketShapePrior == nil ? bucketXY + offset : SIMD2(bucket.point.x,bucket.point.y)' in source
assert 'bucketYawDegrees==0,bucketInwardMeters==0' in source
assert 'var bucketShapePrior: ROBWorkspaceBucketOpeningPrior.Evidence? = nil' in source
with tempfile.TemporaryDirectory(prefix="rob-bucket-prior-") as temporary:
    directory=pathlib.Path(temporary)
    (directory/"Helper.swift").write_text(helper)
    (directory/"Main.swift").write_text(main)
    binary=directory/"fixture"
    subprocess.run(["xcrun","swiftc","-O","-parse-as-library",str(directory/"Helper.swift"),str(directory/"Main.swift"),"-o",str(binary)],check=True)
    subprocess.run([str(binary),*sys.argv[1:]],check=True)
